\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 3200013 (AMR-031-0013). CC BY 4.0. \url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Patrick De Causmaecker and Lennart Van Hirtum, Solving systems of equations on antichains for the computation of the ninth Dedekind Number (2024), §§1,2.1–2.2, pp.1–5. \url{https://arxiv.org/abs/2405.20904}.
\end{description}
